import React, { useState } from "react";
import { Link } from "react-router-dom";
import { ChevronDown, Search, Menu, X } from "lucide-react";

export default function Header() {
  const [selectedLocation, setSelectedLocation] = useState("Select Location");
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleLocationChange = (location) => {
    setSelectedLocation(location);
    setIsDropdownOpen(false);
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      // Do nothing here, as the Link will handle the navigation
    }
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen((prev) => !prev);
  };

  return (
    <header className="bg-white shadow py-4 flex items-center justify-between px-4">
      <Link to="/">
        <img src="/k1.jpeg" alt="Logo" className="w-[100px] h-auto" />
      </Link>
      <div className="flex items-center space-x-4">
        {/* Location Dropdown */}
        <div className="relative">
          <button
            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
            className="flex items-center space-x-2 bg-gray-100 px-4 py-2 rounded-md"
          >
            <span>
              <svg
                className="w-4 h-4 text-gray-600"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M12 2C8.13 2 5 5.13 5 9c0 3.87 7 13 7 13s7-9.13 7-13c0-3.87-3.13-7-7-7z"
                ></path>
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M12 11a2 2 0 100-4 2 2 0 000 4z"
                ></path>
              </svg>
            </span>
            {selectedLocation} <ChevronDown size={16} />
          </button>
          {/* Dropdown Menu */}
          {isDropdownOpen && (
            <div className="absolute mt-2 bg-white shadow-lg rounded-md w-48 z-50 border border-gray-200">
              <ul>
                {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                  <li
                    key={location}
                    onClick={() => handleLocationChange(location)}
                    className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                  >
                    {location}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </div>

      {/* Middle Section: Search Bar */}
      <div className="flex-grow mx-6">
        <form onSubmit={handleSearch} className="flex items-center bg-gray-100 rounded-md">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Find Cars, Mobile Phones and more..."
            className="flex-grow p-2 bg-transparent focus:outline-none"
          />
          <button type="submit" className="p-2 bg-red-500 text-white rounded-r-md">
            <Search size={24} />
          </button>
        </form>
      </div>

      {/* Right Section: Options */}
      <div className="flex items-center space-x-4">
        <button
          onClick={toggleMobileMenu}
          className="block md:hidden text-gray-600 hover:text-gray-800"
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
        <button className="hidden md:block bg-blue-500 text-white px-4 py-2 rounded-md hover:bg-blue-700">
          Login
        </button>
        <Link
          to="/sell"
          className="block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700"
        >
          Sell
        </Link>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-white border-t">
          <div className="px-4 py-4">
            {/* Dropdown for Location */}
            <div className="relative mb-4">
              <button
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
              >
                <span>{selectedLocation}</span> <ChevronDown size={16} />
              </button>
              {isDropdownOpen && (
                <div className="absolute mt-2 bg-white shadow-lg rounded-md w-full z-50 border border-gray-200">
                  <ul>
                    {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                      <li
                        key={location}
                        onClick={() => handleLocationChange(location)}
                        className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                      >
                        {location}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
            {/* Other Options */}
            <div className="space-y-4">
              <button className="text-gray-600 border-b-2 border-transparent hover:border-red-500">Sign up</button>
              <br/>
              <button className="text-gray-600 border-b-2 border-transparent hover:border-red-500">
                Login
              </button>
              <Link
                to="/sell"
                className="block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700"
              >
                Sell
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Categories (Optional) */}
      <div className="container mx-auto px-4 py-2 border-t border-gray-200">
        <div className="flex flex-wrap space-x-4 text-gray-600 justify-center">
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            Vehicles
          </button>
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            Properties
          </button>
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            Mobiles & Tablets
          </button>
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            Jobs
          </button>
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            Electronics & Appliances
          </button>
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            Furniture & Decor
          </button>
          <button className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500">
            More Categories
          </button>
        </div>
      </div>
    </header>
  );
}
